<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Falling Sand</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #0d0f14;
    color: #c8cdd8;
    font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
    gap: 16px;
    padding: 20px;
  }
  h1 {
    font-size: 1.25rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    color: #e8ecf4;
  }
  #sand {
    width: 480px;
    height: 480px;
    max-width: min(480px, 92vw);
    max-height: min(480px, 92vw);
    background: #141820;
    border: 2px solid #2a3140;
    border-radius: 8px;
    cursor: crosshair;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    box-shadow: 0 12px 40px rgba(0,0,0,0.45);
  }
  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    justify-content: center;
    max-width: 520px;
  }
  button {
    appearance: none;
    border: 1px solid #3a4255;
    background: #1a2030;
    color: #d0d6e2;
    padding: 8px 14px;
    border-radius: 6px;
    font-size: 0.875rem;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s, transform 0.1s;
  }
  button:hover {
    background: #242b3d;
    border-color: #5a6578;
  }
  button:active { transform: scale(0.97); }
  button.active {
    border-color: #7eb6ff;
    background: #243044;
    box-shadow: 0 0 0 1px #7eb6ff55;
  }
  #mat-sand.active { border-color: #e0b060; box-shadow: 0 0 0 1px #e0b06055; }
  #mat-water.active { border-color: #4a9eff; box-shadow: 0 0 0 1px #4a9eff55; }
  #mat-wall.active { border-color: #888; box-shadow: 0 0 0 1px #888555; }
  #mat-acid.active { border-color: #50e070; box-shadow: 0 0 0 1px #50e07055; }
  #mat-empty.active { border-color: #c070ff; box-shadow: 0 0 0 1px #c070ff55; }
  #clear { border-color: #a04040; color: #f0a0a0; }
  #clear:hover { background: #302020; }
</style>
</head>
<body>
  <h1>Falling Sand</h1>
  <canvas id="sand"></canvas>
  <div class="controls">
    <button id="mat-sand" class="active">Sand</button>
    <button id="mat-water">Water</button>
    <button id="mat-wall">Wall</button>
    <button id="mat-acid">Acid</button>
    <button id="mat-empty">Eraser</button>
    <button id="clear">Clear</button>
  </div>
<script>
(function () {
  const W = 120;
  const H = 120;
  const EMPTY = 0, SAND = 1, WATER = 2, WALL = 3, ACID = 4;
  const NAMES = ['empty', 'sand', 'water', 'wall', 'acid'];
  const NAME_TO_ID = { empty: EMPTY, sand: SAND, water: WATER, wall: WALL, acid: ACID };

  const COLORS = [
    [0, 0, 0, 0],
    [220, 180, 90, 255],
    [50, 130, 230, 255],
    [100, 105, 115, 255],
    [60, 220, 90, 255],
  ];

  const grid = new Uint8Array(W * H);
  const canvas = document.getElementById('sand');
  const ctx = canvas.getContext('2d');
  canvas.width = W;
  canvas.height = H;
  const img = ctx.createImageData(W, H);
  const pixels = img.data;

  let selected = SAND;
  let painting = false;
  let brush = 2;

  function idx(x, y) { return y * W + x; }

  function inBounds(x, y) {
    return x >= 0 && x < W && y >= 0 && y < H;
  }

  function getCell(x, y) {
    if (!inBounds(x, y)) return WALL;
    return grid[idx(x, y)];
  }

  function setCell(x, y, v) {
    if (!inBounds(x, y)) return;
    grid[idx(x, y)] = v;
  }

  function swap(x1, y1, x2, y2) {
    const a = idx(x1, y1), b = idx(x2, y2);
    const t = grid[a];
    grid[a] = grid[b];
    grid[b] = t;
  }

  function randDir() {
    return Math.random() < 0.5 ? -1 : 1;
  }

  // Process bottom-up so each particle moves at most one cell per step.
  // Sand sinks into liquids by swapping; liquids never move upward.
  function stepOnce() {
    for (let y = H - 1; y >= 0; y--) {
      // Alternate horizontal scan order each row for fairness
      const leftFirst = (y & 1) === 0;
      for (let xi = 0; xi < W; xi++) {
        const x = leftFirst ? xi : (W - 1 - xi);
        const mat = grid[idx(x, y)];
        if (mat === EMPTY || mat === WALL) continue;

        if (mat === SAND) {
          updateSand(x, y);
        } else if (mat === WATER) {
          updateWater(x, y);
        } else if (mat === ACID) {
          updateAcid(x, y);
        }
      }
    }
  }

  function updateSand(x, y) {
    // Fall straight down into empty, or sink by swapping with water/acid
    const below = getCell(x, y + 1);
    if (below === EMPTY) {
      swap(x, y, x, y + 1);
      return;
    }
    if (below === WATER || below === ACID) {
      swap(x, y, x, y + 1);
      return;
    }
    // Diagonal slide
    const d1 = randDir();
    const d2 = -d1;
    for (const d of [d1, d2]) {
      const nx = x + d;
      const under = getCell(nx, y + 1);
      if (under === EMPTY) {
        swap(x, y, nx, y + 1);
        return;
      }
      if (under === WATER || under === ACID) {
        swap(x, y, nx, y + 1);
        return;
      }
    }
  }

  function updateWater(x, y) {
    // Fall down
    if (getCell(x, y + 1) === EMPTY) {
      swap(x, y, x, y + 1);
      return;
    }
    // Diagonal fall
    const d1 = randDir();
    const d2 = -d1;
    for (const d of [d1, d2]) {
      if (getCell(x + d, y + 1) === EMPTY) {
        swap(x, y, x + d, y + 1);
        return;
      }
    }
    // Horizontal spread
    for (const d of [d1, d2]) {
      if (getCell(x + d, y) === EMPTY) {
        swap(x, y, x + d, y);
        return;
      }
    }
  }

  function updateAcid(x, y) {
    // Dissolve neighbors below or beside (sand/wall)
    const neighbors = [
      [x, y + 1],
      [x - 1, y],
      [x + 1, y],
      [x - 1, y + 1],
      [x + 1, y + 1],
    ];
    // Shuffle lightly via random start
    const start = Math.floor(Math.random() * neighbors.length);
    for (let i = 0; i < neighbors.length; i++) {
      const [nx, ny] = neighbors[(start + i) % neighbors.length];
      if (!inBounds(nx, ny)) continue;
      const t = getCell(nx, ny);
      if (t === SAND || t === WALL) {
        // Dissolve target; acid is consumed sometimes for nicer erosion
        setCell(nx, ny, EMPTY);
        if (Math.random() < 0.55) {
          setCell(x, y, EMPTY);
          return;
        }
        break;
      }
    }

    // Move like water
    if (getCell(x, y + 1) === EMPTY) {
      swap(x, y, x, y + 1);
      return;
    }
    const d1 = randDir();
    const d2 = -d1;
    for (const d of [d1, d2]) {
      if (getCell(x + d, y + 1) === EMPTY) {
        swap(x, y, x + d, y + 1);
        return;
      }
    }
    for (const d of [d1, d2]) {
      if (getCell(x + d, y) === EMPTY) {
        swap(x, y, x + d, y);
        return;
      }
    }
  }

  function render() {
    for (let i = 0; i < grid.length; i++) {
      const c = COLORS[grid[i]];
      const p = i * 4;
      if (grid[i] === EMPTY) {
        pixels[p] = 20;
        pixels[p + 1] = 24;
        pixels[p + 2] = 32;
        pixels[p + 3] = 255;
      } else {
        // slight grain for sand
        let r = c[0], g = c[1], b = c[2];
        if (grid[i] === SAND) {
          const n = ((i * 1103515245 + 12345) >>> 16) & 31;
          r = Math.min(255, r + n - 10);
          g = Math.min(255, g + n - 12);
          b = Math.min(255, b + (n >> 2) - 4);
        } else if (grid[i] === WATER) {
          const n = ((i * 1664525 + 1013904223) >>> 16) & 15;
          b = Math.min(255, b + n);
        } else if (grid[i] === ACID) {
          const n = ((i * 214013 + 2531011) >>> 16) & 31;
          g = Math.min(255, g + n - 8);
        }
        pixels[p] = r;
        pixels[p + 1] = g;
        pixels[p + 2] = b;
        pixels[p + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
  }

  function paintAt(clientX, clientY) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const cx = Math.floor((clientX - rect.left) * scaleX);
    const cy = Math.floor((clientY - rect.top) * scaleY);
    for (let dy = -brush; dy <= brush; dy++) {
      for (let dx = -brush; dx <= brush; dx++) {
        if (dx * dx + dy * dy <= brush * brush + 1) {
          const x = cx + dx, y = cy + dy;
          if (!inBounds(x, y)) continue;
          // Don't overwrite wall with sand/water unless placing wall/empty/acid
          const cur = getCell(x, y);
          if (selected === EMPTY || selected === WALL || selected === ACID) {
            setCell(x, y, selected);
          } else if (cur === EMPTY || cur === WATER || cur === SAND || cur === ACID) {
            setCell(x, y, selected);
          }
        }
      }
    }
  }

  // UI
  const matButtons = {
    sand: document.getElementById('mat-sand'),
    water: document.getElementById('mat-water'),
    wall: document.getElementById('mat-wall'),
    acid: document.getElementById('mat-acid'),
    empty: document.getElementById('mat-empty'),
  };
  function setMaterial(name) {
    selected = NAME_TO_ID[name];
    Object.keys(matButtons).forEach(k => {
      matButtons[k].classList.toggle('active', k === name);
    });
  }
  matButtons.sand.addEventListener('click', () => setMaterial('sand'));
  matButtons.water.addEventListener('click', () => setMaterial('water'));
  matButtons.wall.addEventListener('click', () => setMaterial('wall'));
  matButtons.acid.addEventListener('click', () => setMaterial('acid'));
  matButtons.empty.addEventListener('click', () => setMaterial('empty'));

  document.getElementById('clear').addEventListener('click', () => {
    grid.fill(EMPTY);
  });

  canvas.addEventListener('mousedown', (e) => {
    painting = true;
    paintAt(e.clientX, e.clientY);
  });
  window.addEventListener('mouseup', () => { painting = false; });
  canvas.addEventListener('mousemove', (e) => {
    if (painting) paintAt(e.clientX, e.clientY);
  });
  canvas.addEventListener('mouseleave', () => { /* keep painting state until mouseup */ });

  // Touch support
  canvas.addEventListener('touchstart', (e) => {
    e.preventDefault();
    painting = true;
    const t = e.touches[0];
    paintAt(t.clientX, t.clientY);
  }, { passive: false });
  canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    const t = e.touches[0];
    paintAt(t.clientX, t.clientY);
  }, { passive: false });
  window.addEventListener('touchend', () => { painting = false; });

  // API
  window.sim = {
    w: W,
    h: H,
    tick(n) {
      const steps = n | 0;
      for (let i = 0; i < steps; i++) stepOnce();
    },
    get(x, y) {
      if (!inBounds(x, y)) return 'wall';
      return NAMES[grid[idx(x, y)]];
    },
    set(x, y, material) {
      const id = NAME_TO_ID[material];
      if (id === undefined) return;
      setCell(x, y, id);
    },
    clear() {
      grid.fill(EMPTY);
    },
  };

  // Main loop: multiple physics steps per frame for satisfying flow
  function frame() {
    stepOnce();
    stepOnce();
    render();
    requestAnimationFrame(frame);
  }
  render();
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
